(6028204, 886103, 37320, '<td valign="top">That elephant is carrying a huge burden on his back.  Can you draw him some friends to help?</td>', 'That elephant is carrying a huge burden on his back.  Can you draw him some friends to help?', '2010-05-26 10:30:48.000000', NULL, 1),
(6028211, 886129, 37320, '<td valign="top">This is one of my favorites this challenge.</td>', 'This is one of my favorites this challenge.', '2010-05-26 10:33:13.000000', NULL, 1),
(6028217, 885850, 37320, '<td valign="top">Haha for a split second I thought you were filling out a standardized test and I thought It would be a really odd long lost passion.  On closer inspection you are sketching, and I should take more breaks from studying for the GRE.</td>', 'Haha for a split second I thought you were filling out a standardized test and I thought It would be a really odd long lost passion.  On closer inspection you are sketching, and I should take more breaks from studying for the GRE.', '2010-05-26 10:34:39.000000', NULL, 1),
