(6031200, 886073, 114225, '<td valign="top">Fun! My eye keeps getting drawn to the paper the hand is coming out of. It looks like it should be torn paper, but is instead the sleeve of a shirt.</td>', 'Fun! My eye keeps getting drawn to the paper the hand is coming out of. It looks like it should be torn paper, but is instead the sleeve of a shirt.', '2010-05-28 22:03:20.000000', NULL, 1),
(6031201, 885743, 114225, '<td valign="top">Great idea.  Well down with the lighting, perspective, and DOF.</td>', 'Great idea.  Well down with the lighting, perspective, and DOF.', '2010-05-28 22:03:48.000000', NULL, 1),
(6031203, 885395, 114225, '<td valign="top">Not sure how much this counts as art, but  good job with the lighting and scene.</td>', 'Not sure how much this counts as art, but  good job with the lighting and scene.', '2010-05-28 22:04:16.000000', NULL, 1),
(6031205, 885838, 114225, '<td valign="top">I like the used of bokeh, but the spoons feel a bit soft.</td>', 'I like the used of bokeh, but the spoons feel a bit soft.', '2010-05-28 22:05:13.000000', NULL, 1),
