(6031209, 884274, 114225, '<td valign="top">That''s pretty cool. My suggestion would be to diffuse the light a bit more, as the reflections are pretty stark.</td>', 'That''s pretty cool. My suggestion would be to diffuse the light a bit more, as the reflections are pretty stark.', '2010-05-28 22:06:42.000000', NULL, 1),
(6031211, 884732, 114225, '<td valign="top">Very cool. Love the simplicity and colors!</td>', 'Very cool. Love the simplicity and colors!', '2010-05-28 22:07:03.000000', NULL, 1),
(6031212, 885963, 114225, '<td valign="top">Cool collage. Are the light spots the mirrors? Feels like they should be a bit more silvery to me.</td>', 'Cool collage. Are the light spots the mirrors? Feels like they should be a bit more silvery to me.', '2010-05-28 22:07:56.000000', NULL, 1),
(6031213, 885973, 114225, '<td valign="top">That''s cute! Nice tight crop for this shot.</td>', 'That''s cute! Nice tight crop for this shot.', '2010-05-28 22:08:41.000000', NULL, 1),
(6031214, 885728, 114225, '<td valign="top">Good use of low viewpoint. I like the hard shadows, they give the photo more depth.</td>', 'Good use of low viewpoint. I like the hard shadows, they give the photo more depth.', '2010-05-28 22:09:27.000000', NULL, 1),
(6031215, 885318, 114225, '<td valign="top">Cool art! The photo seems to have a lot of noise to it.</td>', 'Cool art! The photo seems to have a lot of noise to it.', '2010-05-28 22:10:12.000000', NULL, 1),
